arguments.command:
export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}";
.claude/skills/agent-emulator-debugging/scripts/drive.py emulate phone;
FILE="/opt/nothingness/media/07-undercover-44.opus";
# normal textScale=1.0
NORMAL_CFG='{"type":"dot","name":"Dot","minDotSize":20.0,"maxDotSize":120.0,"dotOpacity":1.0,"textOpacity":1.0,"sensitivity":1.5,"showSongInfo":true,"textScale":1.0}';
.claude/skills/agent-emulator-debugging/scripts/drive.py pref "screen_config_dot=$NORMAL_CFG":string;
.claude/skills/agent-emulator-debugging/scripts/drive.py screen spectrum;
.claude/skills/agent-emulator-debugging/scripts/drive.py screen dot;
.claude/skills/agent-emulator-debugging/scripts/drive.py play "$FILE";
# give UI a beat to settle
sleep 1.0;
.claude/skills/agent-emulator-debugging/scripts/drive.py shoot dot_songinfo_text_normal;
# max textScale=1.5
MAX_CFG='{"type":"dot","name":"Dot","minDotSize":20.0,"maxDotSize":120.0,"dotOpacity":1.0,"textOpacity":1.0,"sensitivity":1.5,"showSongInfo":true,"textScale":1.5}';
.claude/skills/agent-emulator-debugging/scripts/drive.py pref "screen_config_dot=$MAX_CFG":string;
.claude/skills/agent-emulator-debugging/scripts/drive.py screen spectrum;
.claude/skills/agent-emulator-debugging/scripts/drive.py screen dot;
.claude/skills/agent-emulator-debugging/scripts/drive.py play "$FILE";
sleep 1.0;
.claude/skills/agent-emulator-debugging/scripts/drive.py shoot dot_songinfo_text_max;

